<template>
  <div class="results-container">
    <h1>View Your Connections</h1>
    <div v-if="values" class="results-content">

      <!-- Loading state -->
      <div v-if="!locationConnection" class="loading">
        <p>Finding your connections...</p>
      </div>

      <template v-else>

        <!-- ── LOCATION CONNECTIONS ── -->
        <section class="section">
          <h2>Nearby Connections</h2>

          <div v-if="locationConnection.length === 0" class="no-results">
            <p>No location connections found yet. Check back soon!</p>
          </div>

          <div v-else class="location-connections">
            <!-- Best match — full width, highlighted -->
            <div class="best-match-wrapper">
              <ConnectionCard
                :bestMatch="true"
                :connectionData="{
                  name: locationConnection[0].name,
                  distance: locationConnection[0].distance,
                  connection: locationConnection[0].connection,
                }"
              />
            </div>

            <!-- Remaining results in responsive grid -->
            <div v-if="locationConnection.length > 1" class="card-grid">
              <div
                v-for="(value, key) in locationConnection.slice(1)"
                :key="key"
                class="grid-item"
              >
                <ConnectionCard
                  :bestMatch="false"
                  :connectionData="{
                    name: value.name,
                    distance: value.distance,
                    connection: value.connection,
                  }"
                />
              </div>
            </div>
          </div>
        </section>

        <!-- ── LANGUAGE CONNECTIONS (only shown if user has languages and matches exist) ── -->
        <section v-if="languageConnection && languageConnection.length > 0" class="section">
          <h2>Language Connections</h2>
          <p class="section-subtitle">People who speak one or more of the same languages as you</p>
          <div class="card-grid">
            <div
              v-for="(value, key) in languageConnection"
              :key="key"
              class="grid-item"
            >
              <LanguageCard
                :connectionData="{
                  name: value.name,
                  sharedLanguages: value.sharedLanguages,
                }"
              />
            </div>
          </div>
        </section>

      </template>

      <button @click="goHome" class="home-button">Back to Home</button>
    </div>

    <div v-else class="no-results">
      <p>No form data available</p>
    </div>
  </div>
</template>

<script setup>
import { useRouter } from "vue-router";
import { onMounted, ref, computed } from "vue";
import { useFormStore } from "@/stores/formStore";
import {
  makeLocationConnections,
  makeLanguageConnections,
  submitUserData,
} from "../../Joseph/Backend/backend_module.js";
import ConnectionCard from "@/Components/ConnectionCard.vue";
import LanguageCard from "@/Components/LanguageCard.vue";

const router = useRouter();
const formStore = useFormStore();
const values = computed(() => formStore.getFormData());

const userId = ref(null);
const locationConnection = ref(null);
const languageConnection = ref(null);

onMounted(async () => {
  try {
    const currentValues = formStore.getFormData();
    console.log("Form data retrieved from store:", currentValues);

    const toNum = (v) => {
      const n = parseFloat(v);
      return Number.isFinite(n) ? n : null;
    };

    const payload = {
      ...currentValues,
      highschool_lat: toNum(currentValues.highschool_lat),
      highschool_lon: toNum(currentValues.highschool_lon),
      mis1_lat: toNum(currentValues.mis1_lat),
      mis1_lon: toNum(currentValues.mis1_lon),
      mis2_lat: toNum(currentValues.mis2_lat),
      mis2_lon: toNum(currentValues.mis2_lon),
    };

    const id = await submitUserData(payload, userId.value);
    userId.value = id;
    console.log("Submitted user data, received userId:", id);

    if (id != null) {
      // Run both in parallel
      const [locConn, langConn] = await Promise.all([
        makeLocationConnections(id),
        makeLanguageConnections(id),
      ]);
      locationConnection.value = locConn;
      languageConnection.value = langConn;
      console.log("Location connections:", locConn);
      console.log("Language connections:", langConn);
    } else {
      console.warn("submitUserData returned null id");
      locationConnection.value = [];
      languageConnection.value = [];
    }
  } catch (err) {
    console.error("Error fetching user/location data:", err);
    locationConnection.value = [];
    languageConnection.value = [];
  }
});

function goHome() {
  try { formStore.resetForm(); } catch (e) {}
  try { localStorage.removeItem("formData"); } catch (e) {}
  router.push("/");
}
</script>

<style scoped>
.results-container {
  padding: 1.5rem 1rem;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.results-container h1 {
  font-size: 2rem;
  margin-bottom: 1.5rem;
  text-align: center;
}

@media (max-width: 600px) {
  .results-container h1 { font-size: 1.5rem; }
}

.results-content {
  width: 100%;
  max-width: 900px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2rem;
}

/* Each section (location / language) */
.section {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
}

.section h2 {
  font-size: 1.4rem;
  color: var(--color-primary);
  margin: 0;
  text-align: center;
}

.section-subtitle {
  margin: 0;
  color: #666;
  font-size: .95rem;
  text-align: center;
}

.loading {
  color: #999;
  margin-top: 2rem;
  font-size: 1.1rem;
}

/* Best match card — centered, full width up to its max */
.best-match-wrapper {
  width: 100%;
  display: flex;
  justify-content: center;
}

/* Responsive 2-col grid for remaining cards */
.card-grid {
  width: 100%;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
}

@media (max-width: 600px) {
  .card-grid { grid-template-columns: 1fr; }
}

.grid-item {
  display: flex;
  justify-content: center;
}

.no-results {
  text-align: center;
  color: #999;
  margin-top: 1rem;
}

.home-button {
  display: block;
  margin-top: 1rem;
  padding: .6rem 1.5rem;
  background-color: var(--color-primary);
  color: white;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  font-size: 1rem;
  transition: background .2s;
}

.home-button:hover { background-color: #318760; }
</style>