/* ---------------- USER DATA ---------------- */

export async function getUserData(user_id) {
  if (user_id == null) return null;
  const { data, error } = await supabase.from("users").select().eq("id", user_id).single();
  if (error) { console.error("Error fetching user:", error); return null; }
  return data;
}

export async function getAllOtherUserData(user_id) {
  const { data, error } = await supabase
    .from("users")
    .select()
    .neq("id", user_id);
  if (error) { console.error("Error fetching data:", error); return null; }
  return data;
}

export async function submitUserData(userData, userID = null) {
  const fields = {
    full_name:       userData.full_name,
    languages:       userData.languages,
    highschool_name: userData.highschool_name,
    highschool_lat:  userData.highschool_lat,
    highschool_lon:  userData.highschool_lon,
    mis1_name:       userData.mis1_name,
    mis1_lat:        userData.mis1_lat,
    mis1_lon:        userData.mis1_lon,
    mis2_name:       userData.mis2_name,
    mis2_lat:        userData.mis2_lat,
    mis2_lon:        userData.mis2_lon,
    time_entered:    new Date().toISOString(),
  };

  let data, error;

  if (userID != null) {
    ({ data, error } = await supabase.from("users").update(fields).eq("id", userID).select());
    if (error) { console.error("Error updating data:", error); return null; }
    console.log("Data successfully updated");
    return data[0].id;
  }

  ({ data, error } = await supabase.from("users").select().eq("full_name", fields.full_name));
  if (error) { console.error("Error checking for matching data:", error); return null; }

  if (data.length === 0) {
    ({ data, error } = await supabase.from("users").insert(fields).select());
    if (error) { console.error("Error inserting data:", error); return null; }
    console.log(`Successfully inserted data at row ${data[0].id}`);
    return data[0].id;
  } else {
    ({ data, error } = await supabase.from("users").update(fields).select().eq("full_name", fields.full_name));
    if (error) { console.error(`Error updating data for user ${fields.full_name}:`, error); return null; }
    console.log(`Successfully updated data at row ${data[0].id}`);
    return data[0].id;
  }
}

/* ---------------- CONNECTIONS ---------------- */

export async function makeLocationConnections(userID) {
  const user = await getUserData(userID);
  console.log("user:", user);

  const userLocations = {};
  if (user.highschool_lat != null && user.highschool_lon != null) {
    userLocations.highschool = { name: user.highschool_name, lat: user.highschool_lat, lon: user.highschool_lon };
  }
  if (user.mis1_lat != null && user.mis1_lon != null) {
    userLocations.mis1 = { name: user.mis1_name, lat: user.mis1_lat, lon: user.mis1_lon };
  }
  if (user.mis2_lat != null && user.mis2_lon != null) {
    userLocations.mis2 = { name: user.mis2_name, lat: user.mis2_lat, lon: user.mis2_lon };
  }

  if (Object.keys(userLocations).length === 0) return [];

  const locationLabels = {
    highschool: "went to high school",
    mis1: "served a mission",
    mis2: "served a mission",
  };

  const data = await getAllOtherUserData(userID);
  console.log("all others:", data);
  const results = [];

  data.forEach((person) => {
    const personLocations = {};
    if (person.highschool_lat != null && person.highschool_lon != null) {
      personLocations.highschool = { name: person.highschool_name, lat: person.highschool_lat, lon: person.highschool_lon };
    }
    if (person.mis1_lat != null && person.mis1_lon != null) {
      personLocations.mis1 = { name: person.mis1_name, lat: person.mis1_lat, lon: person.mis1_lon };
    }
    if (person.mis2_lat != null && person.mis2_lon != null) {
      personLocations.mis2 = { name: person.mis2_name, lat: person.mis2_lat, lon: person.mis2_lon };
    }

    if (Object.keys(personLocations).length === 0) return;

    let closestDistance = Infinity;
    let closestConnection = "";

    for (const [userLocKey, userLoc] of Object.entries(userLocations)) {
      for (const [personLocKey, personLoc] of Object.entries(personLocations)) {
        const distance = Math.round(haversine(userLoc.lat, userLoc.lon, personLoc.lat, personLoc.lon));
        if (distance < closestDistance) {
          closestDistance = distance;
          const personAction = personLocKey === "highschool" ? "graduated" : "served a mission";
          const userAction = locationLabels[userLocKey];
          closestConnection = `${personAction} in ${personLoc.name} ${distance} miles from where you ${userAction}`;
        }
      }
    }

    results.push({ name: person.full_name, distance: closestDistance, connection: closestConnection });
  });

  return results.sort((a, b) => a.distance - b.distance);
}

export async function makeLanguageConnections(userID) {
  const user = await getUserData(userID);

  const userLanguages = parseLanguages(user.languages);
  if (userLanguages.length === 0) return [];

  const others = await getAllOtherUserData(userID);
  if (!others || others.length === 0) return [];

  const results = [];

  others.forEach((person) => {
    const personLanguages = parseLanguages(person.languages);
    if (personLanguages.length === 0) return;

    const shared = userLanguages.filter(lang =>
      personLanguages.some(pl => pl.toLowerCase() === lang.toLowerCase())
    );

    if (shared.length > 0) {
      results.push({
        name: person.full_name,
        sharedLanguages: shared,
      });
    }
  });

  return results.sort((a, b) => b.sharedLanguages.length - a.sharedLanguages.length);
}

/* ---------------- HAVERSINE ---------------- */

function haversine(lat1, lon1, lat2, lon2) {
  const R = 3959;
  const toRad = (angle) => (angle * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLon = toRad(lon2 - lon1);
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) *
    Math.sin(dLon / 2) * Math.sin(dLon / 2);
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}